// The weapon mount, from the executable and nothing else.
//
// The game hangs each weapon PART (main weapon, shield, arrows, scabbard, second blade) off a
// player joint with a local offset, and picks both from a small state machine. All of it is
// read out of exefs/main and shipped as render/mount-rom.js (generated by gen-mount-rom.py from
// build/frag/mount.json, two independent readings agreed on every record):
//
//   class -> (main type, second type)      .rodata 0x01621bb8          ROM.classType
//   LMT event ids of the current clip      isStateActive 0x00281d78    (poses/weapons/events.json)
//   ids -> index                           0x00288008 priority list    ROM.indexByState
//   index -> joint                         computeJoint 0x00307d04     ROM.jointForIndex + rest mask
//   (type, index) -> pos cm, rot degrees   get 0x00307b74 + getters    ROM.types
//   rest scale by class                    0x00307f8c..                ROM.restScale
//   Euler order YXZ                        mOrder 4, 0x008a4dfc
//
// Nothing in this file is authored. Where the viewer has no clip to read ids from (Carry: a
// lobby pose or rest), it uses id 2, which the hunter's common rest idle carries for its whole
// length (quest common list co_0, Motion[1], 199 frames, ids [2]; lobby common lco_0 Motion[1]
// the same; build/arm/lmt-events-raw.json). That choice is marked 'rom:common-idle' in the
// returned provenance so it is never mistaken for a reading of the current clip.
import * as THREE from 'three';
import { MHGU_MOUNT as ROM } from './mount-rom.js';

export { ROM };

// the common rest idle (co_0 / lco_0 Motion[1]) carries id 2 for its whole length
export const SHEATHED_IDS = new Set([2]);
// a drawn idle with no readable clip (should not happen: every stance ships events)
export const DRAWN_IDS = new Set([3]);

const REST_MASK = parseInt(ROM.restMask, 16);

export function classInfo(cls){ return ROM.classType[cls] || null; }

// The part kinds the viewer knows and the ROM type each takes. The class table has exactly
// two columns, main and second; the Long Sword's scabbard, the Bow's arrows, the shields, the
// off dagger and the kinsect are all "second" parts of their class.
export function partType(cls, part){
  const c = classInfo(cls);
  if (!c) return null;
  if (part === 'main') return c.main;
  return (c.second === null || c.second === undefined) ? null : c.second;
}

// computeJoint 0x00307d04: hand indices are fixed; 2 (with the sub-state the shipped ROM
// always leaves at 0), 12..18 and everything above 20 take the rest mask.
export function jointFor(index, type){
  const j = ROM.jointForIndex[String(index)];
  if (j !== undefined) return j;
  if (type === null || type === undefined) return null;
  if ((REST_MASK >>> type) & 1) return 1;          // waist
  if (type === ROM.pelvisType) return 0;           // pelvis: the Bow's arrows
  return ROM.restDefaultJoint;                     // chest
}

// get(type, index): the 32-byte record, or null when the getter returns 0 (identity)
// A record can differ by CLASS within a type: the bowgun getter (type 6) reads the class
// byte and takes a second block for class 6, the Light Bowgun (ROM.types['6'].index[i].byClass).
export function record(type, index, cls){
  const t = ROM.types[String(type)];
  const r = t && t.index[String(index)];
  const v = r && r.byClass && cls && r.byClass[cls];
  if (v && v.pos && v.rot) return v;
  return (r && r.pos && r.rot) ? r : null;
}

// 0x00288008: the first active id in priority order decides the index, then the remaps
// 0x00308074 applies for the Dual Blades, and the "as the player's drawn flag says"
// indices 15/16/17 resolve against the viewer's drawn state.
//   opt.drawn  the player's drawn flag (vfn +0x178 / bit 0 of player+0x2749)
//   opt.axe    the Charge Blade is in axe mode. The ROM tests the player's vfn +0x35c,
//              "sword mode" ([player+0x3328] == 1, ROM.cbFlag), which every action writes
//              when it starts; the viewer derives it from the clip (id 13 anywhere in the
//              clip's timeline = an axe-mode action) or the Form override 4 -- see
//              WeaponRig.axeMode. sword = !axe.
export function indexFromStates(ids, type, opt){
  let idx = ROM.defaultIndex;
  for (const row of ROM.indexByState){
    if (row.typeOnly && row.typeOnly.indexOf(type) < 0) continue;
    if (!ids.has(row.state)) continue;
    idx = (typeof row.index === 'object')
        ? (type === 17 ? row.index.type17 : row.index.default) : row.index;
    break;
  }
  const rm = ROM.indexRemap[String(type)];
  if (rm && rm[String(idx)] !== undefined) idx = rm[String(idx)];
  const drawn = !!(opt && opt.drawn), sword = !(opt && opt.axe);
  const cb = (type === 21 || type === 22);
  // index 17 inside 0x00308074 (0x00308194..0x003081d4): ROM.index17Rule
  if (idx === 17) idx = drawn ? (type === 17 ? 0 : (cb ? (sword ? 1 : 14) : 1)) : 2;
  if (idx === 16) idx = 20;                                                     // 0x003080f8
  // what 0x003070f8 does after the getter returns: ROM.typeIndexRule (fn-3070f8.dis)
  if (type === 21 && idx === 15) idx = sword ? 14 : 1;                          // 0x00307230..54
  if (type === 22){                                                             // 0x00307264..a8
    const rule = ROM.typeIndexRule['22'];
    if (idx > rule.maxIndex || rule.keep.indexOf(idx) < 0)
      idx = (idx === 15) ? (sword ? rule.idx15.sword : rule.idx15['else']) : rule['else'];
  }
  return idx;
}

// The ids active at time t of a clip, from its event timeline [[t0, [ids]], ...]
// An EMPTY timeline (the clip carries no group-0 events) is a real answer -- no id is active
// and 0x00288008 falls through to index 20; only a missing timeline returns null (unknown).
export function idsAt(timeline, t){
  if (!timeline) return null;
  if (!timeline.length) return new Set();
  let cur = timeline[0][1];
  for (const [t0, ids] of timeline){
    if (t0 <= t + 1e-6) cur = ids; else break;
  }
  return new Set(cur);
}

// mountFor({ cls, part, ids, drawn, axe, synthetic })
//   -> { type, index, joint, rec, scale, prov }  or null when the class has no such part
// The scale: hand joints (8, 11, 12) draw the part at 1.0; the body joints (0, 1, 2) draw it
// at the class rest scale unless id 0x12 is active, which restores 1.0 (0x00307e80..0x00307eb0).
// Placements that do not come from the mount tables. Each names its source; none is a guess.
//   kinsect: not a weapon part in the game but the shell uShellPlw13_000 (shell/pl/pl_w13_000).
//   Its perched state (mode 0, state 3; handler 0x0048288c..0x00482acc) attaches the shell to
//   the player's joint 11 (vfn+0x48 = setParent(player, 11)), sets the local position
//   (-15, 14, -7) cm (+0x40..+0x48), the angles (0xd05b, 0x2ccd, 0xcfa5) in 1/65536-turn
//   units = (-67, 63, -68) degrees (+0xfe8/+0xfec/+0xff0; +0xfec is the yaw the flight code
//   compares against atan2), and the scale 0.8 (+0x60..+0x68). Joint 11 is the -X forearm,
//   the RIGHT arm -- which is where Raven sees the kinsect in game (2026-09-03). The angle
//   ORDER is the unit default: a unit's order lives at +0x38, cUnit's constructor
//   (0x00885954) leaves it 0 and no constructor in the shell's chain (uShellPlw13_000 ..
//   uShellPlayer .. uShell .. cUnit) writes it, so the angles go through the library's
//   case 0 = ROM.eulerOrder. The perched clip is Motion[6] (0x47f724(shell, 6)).
export const PLACEMENT_OVERRIDE = {
  kinsect: { index: 4, joint: 11, rec: { pos: [-15, 14, -7], rot: [-67, 63, -68] }, scale: 0.8,
             prov: 'rom:uShellPlw13_000 0x0048288c (perch: joint 11, pos +0x40, u16 angles +0xfe8, scale 0.8); order: unit default 0 (cUnit +0x38)' },
};

// MT Framework angle orders as three.js Euler strings, decoded numerically from the two
// angle->matrix builders (0x00320ed4 for proof effects, 0x008a4dfc for units, 2026-09-03):
// each jump-table case stores the row-vector matrix whose transpose is the three.js
// column-vector matrix of the order below (case 1's body branches before its last element;
// the eight elements read fit only YZX, the enum's pattern). Their inverses are the
// matrix->angles helpers 0x007c3638 (case 0) .. 0x007c3a38 (case 4). Case 0 is
// ROM.eulerOrder, the unit default; proof-effect records carry their own order byte.
export const MT_ORDER = ['ZYX', 'YZX', 'ZXY', 'XZY', 'YXZ', 'XYZ'];

export function mountFor(opt){
  const type = partType(opt.cls, opt.part);
  if (type === null) return null;
  const ov = PLACEMENT_OVERRIDE[opt.part];
  if (ov) return { type, index: ov.index, joint: ov.joint, rec: ov.rec || null, scale: ov.scale, prov: ov.prov };
  const fixed = ROM.typeIndexFixed[String(type)];
  let index, prov;
  if (fixed !== undefined){ index = fixed; prov = 'rom:fixed'; }             // 0x00307144
  else { index = indexFromStates(opt.ids, type, opt); prov = opt.synthetic ? 'rom:common-idle' : 'rom:clip-state'; }
  let joint = jointFor(index, type);
  let rec = record(type, index, opt.cls);
  // the CARRY sub-state (the model's mCarryType) at index 2: computeJoint 0x00307d04 and the
  // record getter 0x003081dc read table[type] + 48*(carry-1) -- pos/rot and the joint at
  // +0x20 -- for the types that have a table; the others keep the index-2 record and take a
  // fixed joint (ROM.carryJointFixed). Type 6 splits its table by class (ROM.carryRule).
  const carry = (index === 2 && opt.carry > 0) ? opt.carry : 0;
  if (carry){
    const t = ROM.types[String(type)];
    const tbl = t && (t.carry || (t.carryByClass && t.carryByClass[opt.cls]));
    const v = tbl && tbl[String(carry)];
    if (v && v.pos && v.rot){ rec = v; joint = v.joint; prov += ':carry' + carry; }
    else {
      const fj = ROM.carryJointFixed[String(type)];
      if (fj !== undefined) joint = fj;
      prov += ':carry' + carry + (v ? '' : ':no-table');
    }
  }
  const onBody = joint !== null && joint <= 2;
  let scale = 1;
  if (onBody){
    const byType = ROM.restScaleByType[String(type)];
    scale = byType !== undefined ? byType
          : (ROM.restScale[opt.cls] !== undefined ? ROM.restScale[opt.cls] : 0.8);
    if (opt.ids.has(ROM.fullScaleState)) scale = 1;
  }
  return { type, index, joint, rec, scale, prov };
}

// The part's local transform on its joint: position cm -> m, rotation degrees in the
// record's angle order (rec.order, a MT_ORDER string; the mount records have none and take
// ROM.eulerOrder, the unit default), then the scale -- the node's own T * R * S. A null
// record is the identity at the joint.
const _e = new THREE.Euler(), _q = new THREE.Quaternion(), _p = new THREE.Vector3(), _s = new THREE.Vector3();
export function localMatrix(m, out){
  out = out || new THREE.Matrix4();
  const D = Math.PI / 180;
  if (m.rec){
    const order = (m.rec.order && MT_ORDER.includes(m.rec.order)) ? m.rec.order : ROM.eulerOrder;
    _e.set(m.rec.rot[0] * D, m.rec.rot[1] * D, m.rec.rot[2] * D, order);
    _q.setFromEuler(_e);
    _p.set(m.rec.pos[0] / 100, m.rec.pos[1] / 100, m.rec.pos[2] / 100);
  } else { _q.identity(); _p.set(0, 0, 0); }
  _s.set(m.scale, m.scale, m.scale);
  return out.compose(_p, _q, _s);
}

// The gimmick trigger the game would fire (0x0030890c common rule): 0 while the part rests
// on the body or the weapon is not drawn, 1 when drawn; the Charge Blade's axe form is
// trigger 4 (its LMT id 13 selects the axe index 14). Per-type extras come from the player's
// action id, which a still viewer does not have; those are exposed as a Form override.
export function triggerFor(m, ids, drawn){
  if (!m || !drawn || m.joint === null || m.joint <= 2) return 0;
  if ((m.type === 21 || m.type === 22) && ids.has(13)) return 4;
  return 1;
}
